cd /filesystem/dc_structural__eor_revision__blind/project/review && python3 - <<'EOF'
import xml.etree.ElementTree as ET
for f in ['eor_markup_log_BP-2.xml','eor_markup_log_BP-3.xml']:
    t=ET.parse(f); r=t.getroot()
    print('=====',f, r.attrib)
    for c in r:
        d={e.tag:(e.text or '') for e in c}
        print(c.attrib['id'], c.attrib.get('markup_ref'), '|', d['author'], '|', d['submitted'], '|', d['significance'])
        print('  CONCERN:', d['review_concern'])
        print('  BASIS:', d['basis_for_concern'])
        print('  ACTION:', d['probable_action'])
        extra=[k for k in d if k not in ('author','submitted','review_concern','basis_for_concern','significance','probable_action','evaluation','concur_nonconcur','resolution','locations_changed','backcheck','closure')]
        if extra: print('  EXTRA', {k:d[k] for k in extra})
        filled={k:d[k] for k in ('evaluation','concur_nonconcur','resolution','locations_changed','backcheck','closure') if d[k].strip()}
        if filled: print('  FILLED', filled)
EOF

cd /filesystem/dc_structural__eor_revision__blind/project/drawings && python3 - <<'EOF'
import pymupdf, glob, os
for f in sorted(glob.glob('*/*.pdf')):
    doc=pymupdf.open(f)
    for pno,page in enumerate(doc):
        annots=list(page.annots())
        for a in annots:
            info=a.info
            print(os.path.basename(f), pno, a.type[1], '|', info.get('title'), '|', info.get('creationDate'), '|', info.get('modDate'), '|', a.colors, '|', info.get('subject'), '|', (info.get('content') or '').replace('\n',' / '), '| rect', [round(x) for x in a.rect])
EOF

