#!/usr/bin/env python3
"""Self-check: find verbatim runs of >=16 words (words = runs of 2+ letters) shared with shipped standards."""
import re, glob, os, sys, zipfile, io, csv
import openpyxl

N = 16
SRC = sorted(glob.glob('/tmp/work/txt/*.raw.txt'))
# contract XML text
import xml.etree.ElementTree as ET
extra = []
for f in glob.glob('/filesystem/dc_structural__eor_revision__blind/project/contract/*.xml'):
    t = open(f).read()
    t = re.sub(r'<[^>]+>', ' ', t)
    extra.append((os.path.basename(f), t))

def words(t):
    return [w.lower() for w in re.findall(r'[A-Za-z]{2,}', t)]

grams = {}
def add_src(name, text):
    w = words(text)
    for i in range(len(w) - N + 1):
        g = ' '.join(w[i:i + N])
        grams.setdefault(g, name)

for f in SRC:
    add_src(os.path.basename(f), open(f, errors='ignore').read())
for name, t in extra:
    add_src(name, t)

def check_text(label, text):
    w = words(text)
    hits = []
    i = 0
    while i <= len(w) - N:
        g = ' '.join(w[i:i + N])
        if g in grams:
            # extend
            j = i + N
            while j < len(w) and ' '.join(w[j - N + 1:j + 1]) in grams:
                j += 1
            hits.append((grams[g], ' '.join(w[i:j])))
            i = j
        else:
            i += 1
    for src, h in hits:
        print('HIT', label, '<-', src, ':', h)
    return len(hits)

def texts_from_zip(path):
    z = zipfile.ZipFile(path)
    out = []
    for n in z.namelist():
        data = z.read(n)
        if n.endswith('.xlsx'):
            wb = openpyxl.load_workbook(io.BytesIO(data))
            parts = []
            for ws in wb.worksheets:
                for row in ws.iter_rows(values_only=True):
                    parts.append(' | '.join('' if v is None else str(v) for v in row))
            out.append((n, '\n'.join(parts)))
        else:
            out.append((n, data.decode('utf-8')))
    return out

if __name__ == '__main__':
    path = sys.argv[1] if len(sys.argv) > 1 else '/filesystem/dc_structural__eor_revision__blind/output/submission.zip'
    total = 0
    for n, t in texts_from_zip(path):
        # check whole document and per cell/line
        total += check_text(n, t)
    print('total hits', total)

