"""Self-check: list clause numbers presented as authority and verify each appears in some shipped document."""
import re, glob, os, sys, zipfile, io
sys.path.insert(0, '/tmp/work/py')
from check_license import texts_from_zip

DOCS = {}
for f in glob.glob('/tmp/work/txt/*.txt'):
    if f.endswith('.raw.txt'):
        continue
