for f in glob.glob('/filesystem/dc_structural__eor_revision__blind/project/contract/*.xml'):
    DOCS[os.path.basename(f)] = re.sub(r'<[^>]+>', ' ', open(f).read())
ALL = '\n'.join(DOCS.values())

CLAUSE_WORDS = r'(?:§|sections?|clauses?|paragraphs?|para\.?|tables?|figures?|appendix|appendices|chapters?|articles?|items?)'
DOC_NAMES = r'(?:FC 1-300-09N|ER 415-1-11|ER 1165-2-217|ER 1110-1-8159|FAR|SR-21-6|SR-24-3|SR-23-1|UFC 1-300-09N|Release 6\.2|Release 2\.2|Release 6\.0)'
NUM = r'([A-Z]?\d+(?:[.\-]\d+)*(?:\.[a-z])?(?:\(\d+\))?)'

pat1 = re.compile(CLAUSE_WORDS + r'\s+' + NUM, re.I)
pat2 = re.compile(DOC_NAMES + r'[\s,]+' + NUM)

def check(label, text):
    found = set()
    for m in pat1.finditer(text):
        found.add(('cw', m.group(0), m.group(1)))
    for m in pat2.finditer(text):
        found.add(('dn', m.group(0), m.group(1)))
    bad = []
    for kind, ctx, num in sorted(found, key=lambda x: x[2]):
        ok = num in ALL
        if not ok:
            bad.append((ctx, num))
    return found, bad

if __name__ == '__main__':
