    allnums = set()
    for n, t in texts_from_zip(path):
        found, bad = check(n, t)
        for f in found:
            allnums.add(f[2])
        for b in bad:
            print('NOT FOUND', n, b)
    print('cited numbers:', sorted(allnums))
